import {
  Component,
  Host,
  Prop,
  State,
  h,
  Watch,
  Listen,
  Event,
  EventEmitter,
} from '@stencil/core';
import {
  getQrCodeImageUrl,
  useDevice,
  getHashParams,
} from './../../utils/utils';
import { registerInterFont } from './../../utils/interFont';
import { createTranslateFunction } from './localization';
import { Alert, StartButton, CancelButton } from './components';
import axios from 'axios';

@Component({
  tag: 'jgroup-bank-id',
  styleUrl: 'jgroup-bank-id.css',
  shadow: true,
  assetsDirs: ['./../assets'],
})
export class JgroupBankId {
  /** Events */
  /** Fired whenever the widget returns to its idle state - the cancel button, "try again" after a failure, or an unexpected drop mid-flow. Use it to reset any "a BankID attempt is in progress" state a consuming app keeps of its own. */
  @Event() cancelled!: EventEmitter;
  /** Fired once collect() resolves with a terminal 'complete' status - detail carries the raw collect response, success or business-logic error. */
  @Event() completed!: EventEmitter;
  /** Fired once the initial auth/sign request has succeeded and a transaction is under way - detail carries { flowType }, so consumers can tell the same-device app hand-off (flowType: 'app', which then shows nothing of its own until the visitor returns) apart from the qr flow's own continuously-updating UI. */
  @Event() started!: EventEmitter;

  /** Props */
  /** Whether this widget performs an authentication or a signing flow. */
  @Prop() readonly type!: 'auth' | 'sign';
  /** Endpoint that starts a signing transaction - required when type is 'sign'. */
  @Prop() readonly signUrl!: string;
  /** Endpoint that starts an authentication transaction - required when type is 'auth'. */
  @Prop() readonly authUrl!: string;
  /** Endpoint polled for the transaction's current status. */
  @Prop() readonly collectUrl!: string;
  /** Endpoint called to cancel an in-progress transaction. */
  @Prop() readonly cancelUrl!: string;
  /** Auto-starts the flow immediately on mount, skipping the start button - desktop (qr flow) only. */
  @Prop() readonly autoStartSingleOption = false;
  /** Renders the widget with its dark color scheme. */
  @Prop() readonly darkTheme = false;
  /** UI language for all widget copy. */
  @Prop() readonly language: 'sv' | 'en' = 'sv';

  /** Watchers for prop validation */
  @Watch('type')
  validateType(newValue: string) {
    if (!['auth', 'sign'].includes(newValue)) {
      this.throwError(
        'The `type` attribute is required and must be either `auth` or `sign`.',
      );
    }
  }

  @Watch('signUrl')
  validateSignUrl(newValue: string) {
    if (this.type === 'sign' && newValue === undefined) {
      this.throwError(
        'The `sign-url` attribute is required when `type` is set to `sign`.',
      );
    }
  }

  @Watch('authUrl')
  validateAuthUrl(newValue: string) {
    if (this.type === 'auth' && newValue === undefined) {
      this.throwError(
        'The `auth-url` attribute is required when `type` is set to `auth`.',
      );
    }
  }

  @Watch('collectUrl')
  validateCollectUrl(newValue: string) {
    if (newValue === undefined) {
      this.throwError('The `collect-url` attribute is required.');
    }
  }

  @Watch('cancelUrl')
  validateCancelUrl(newValue: string) {
    if (newValue === undefined) {
      this.throwError('The `cancel-url` attribute is required.');
    }
  }

  /** Visibility change listener */
  @Listen('visibilitychange', { target: 'document' })
  handleVisibilityChange() {
    if (document.visibilityState === 'hidden') return;

    const hashParams: { initiated?: string } = getHashParams(location.hash);
    const userStarted = window.history.state?.triggeredByUser === true;
    const flowInitiated = hashParams.initiated !== undefined;

    // Only resume polling if the flow was genuinely started
    if (
      this.isInProgress &&
      !this.isPolling &&
      this.currentTransactionId &&
      (flowInitiated || userStarted)
    ) {
      this.pollCollect(this.currentTransactionId);
    }
  }

  /** State */
  @State() flowType!: 'app' | 'qr';
  @State() isMobileOrTablet: boolean = false;
  @State() isStarting: boolean = false;
  @State() isStartingOnAnotherDevice: boolean = false;
  @State() isInProgress: boolean = false;
  @State() isCancelling: boolean = false;
  @State() statusHintCode: string | null = null;
  @State() status: string | null = null;
  @State() qrCodeImageUrl: string | null = null;

  /** Internal */
  private axios = axios.create({ withCredentials: true, withXSRFToken: true });
  private TAG = '[jgroup-bank-id]';
  private propsValid = true;
  private propsValidationErrorMessage: string | null = null;
  private translate = createTranslateFunction(this.language);
  private isPolling = false;
  private currentTransactionId: string | null = null;

  /** Lifecycle */
  componentWillLoad() {
    registerInterFont();
    this.validateProps();
    window.history.replaceState({}, '', null);

    this.init = this.init.bind(this);
    this.startOnAnotherDevice = this.startOnAnotherDevice.bind(this);
    this.pollCollect = this.pollCollect.bind(this);
    this.reset = this.reset.bind(this);
    this.cancel = this.cancel.bind(this);
    this.setFlowTypeBasedOnDevice();

    if (
      this.autoStartSingleOption &&
      !this.isMobileOrTablet &&
      this.flowType === 'qr'
    ) {
      setTimeout(() => this.init(), 0);
    }
  }

  /** UI Rendering */
  render() {
    if (!this.propsValid) {
      return (
        <p role='alert'>{this.propsValidationErrorMessage}</p>
      );
    }

    return (
      <Host>
        {this.shouldRenderStartButtons && (
          <div class='flex flex-col items-center'>
            <StartButton
              isOutlined={false}
              darkTheme={this.darkTheme}
              onClick={this.init}
              isLoading={this.isStarting && !this.isStartingOnAnotherDevice}
              text={
                this.flowType === 'qr' && !this.isStartingOnAnotherDevice
                  ? this.translate('start-qr')
                  : this.translate('start-app')
              }
            />
            {this.isMobileOrTablet && (
              <div class='mt-4'>
                <StartButton
                  isOutlined={true}
                  darkTheme={this.darkTheme}
                  onClick={this.startOnAnotherDevice}
                  isLoading={this.isStarting && this.isStartingOnAnotherDevice}
                  text={this.translate('start-qr-another-device')}
                />
              </div>
            )}
          </div>
        )}

        {this.shouldRenderStatusHint && (
          <Alert
            message={this.translate(
              `hintcode-${this.flowType}-${this.statusHintCode || 'unknown'}`,
              `hintcode-${this.statusHintCode || 'unknown'}`,
            )}
            type={this.status === 'failed' ? 'error' : 'info'}
            tryAgainButtonText={this.translate('try-again')}
            onTryAgainButtonClick={this.reset}
            darkTheme={this.darkTheme}
          />
        )}

        {this.shouldRenderQrImage && (
          <div
            class={{
              'w-fit mx-auto mb-4 p-3 rounded-xl animate-fade': true,
              'bg-white border border-gray-200': !this.darkTheme,
              'bg-neutral-800 border border-neutral-700': this.darkTheme,
            }}
          >
            <img
              src={this.qrCodeImageUrl ?? undefined}
              alt={this.translate('qr-code-alt')}
              class='block rounded-lg'
            />
          </div>
        )}

        {this.shouldRenderAppInProgressMessage && (
          <p
            data-test-id='app-in-progress-message'
            aria-live='polite'
            class='text-center animate-fade'
          >
            {this.translate('app-in-progress')}
          </p>
        )}

        {this.shouldRenderCancelButton && (
          <p class='text-center animate-fade'>
            <CancelButton
              onClick={this.cancel}
              text={this.translate('cancel')}
              isLoading={this.isCancelling}
              darkTheme={this.darkTheme}
            />
          </p>
        )}
      </Host>
    );
  }

  /** Computed */
  private get shouldRenderCancelButton() {
    return this.flowType === 'qr' && (this.isInProgress || this.isCancelling);
  }

  private get shouldRenderQrImage() {
    return (
      this.isInProgress &&
      this.flowType === 'qr' &&
      this.qrCodeImageUrl !== null
    );
  }

  // The app flow never polls collect-url until the visitor returns from
  // the native app (see handleVisibilityChange), so statusHintCode - the
  // only other thing that renders anything for the app flow, via the
  // Alert below - stays null the entire time the visitor is away. Without
  // this, the widget renders nothing at all for that whole stretch.
  private get shouldRenderAppInProgressMessage() {
    return (
      this.isInProgress &&
      this.flowType === 'app' &&
      this.statusHintCode === null
    );
  }

  private get shouldRenderStatusHint() {
    return this.statusHintCode !== null && this.isInProgress !== null;
  }

  private get shouldRenderStartButtons() {
    return (
      !this.isInProgress &&
      this.status !== 'complete' &&
      this.statusHintCode === null
    );
  }

  /** Actions */
  private startOnAnotherDevice() {
    this.isStartingOnAnotherDevice = true;
    this.flowType = 'qr';
    this.init();
  }

  private setFlowTypeBasedOnDevice() {
    const { isMobileOrTablet } = useDevice();
    this.isMobileOrTablet = isMobileOrTablet;
    this.flowType = isMobileOrTablet ? 'app' : 'qr';
  }

  private validateProps() {
    try {
      this.validateType(this.type);
      this.validateSignUrl(this.signUrl);
      this.validateAuthUrl(this.authUrl);
      this.validateCollectUrl(this.collectUrl);
      this.validateCancelUrl(this.cancelUrl);
    } catch (error: any) {
      this.propsValid = false;
      this.propsValidationErrorMessage = error.message;
      console.error(error);
    }
  }

  private throwError(message: string) {
    throw new Error(`${this.TAG} ${message}`);
  }

  private async init() {
    const url = this.type === 'auth' ? this.authUrl : this.signUrl;
    this.isStarting = true;

    const transaction = await this.post(url);

    if (!transaction) {
      console.error(`${this.TAG} Failed starting '${this.type}' transaction`);
      await this.reset();
      return;
    }

    this.started.emit({ flowType: this.flowType });
    window.history.pushState({ triggeredByUser: true }, '', null);
    await this.handleInitComplete(transaction);
  }

  private async handleInitComplete({
    autoStartToken,
    transactionId,
  }: {
    autoStartToken: string;
    transactionId: string;
  }) {
    this.currentTransactionId = transactionId;
    this.isInProgress = true;
    if (this.flowType === 'qr') {
      this.isStarting = false;
      await this.pollCollect(transactionId);
    } else if (this.flowType === 'app') {
      const returnUrl = this.createReturnUrl();
      window.location.href = `https://app.bankid.com/?autostarttoken=${autoStartToken}&redirect=${returnUrl}`;
    }
  }

  private async pollCollect(transactionId: string | null = null) {
    if (this.isPolling || !this.isInProgress) return;

    this.isPolling = true;

    while (this.isPolling && !this.isCancelling) {
      const response = await this.post(this.collectUrl);

      if (!response) {
        console.warn(`${this.TAG} pollCollect returned null`);
        this.isPolling = false;
        await this.reset();
        break;
      }

      if (transactionId && response.transactionId !== transactionId) {
        console.error(`${this.TAG} transactionId mismatch`);
        this.isPolling = false;
        await this.reset();
        break;
      }

      if (this.flowType === 'qr') {
        this.qrCodeImageUrl = await getQrCodeImageUrl(response.qrCode);
      }

      this.statusHintCode = response.hintCode;
      this.status = response.status;

      switch (response.status) {
        case 'pending':
          await this.delay(1000);
          break;

        case 'failed':
          this.isPolling = false;
          this.isInProgress = false;
          this.isStarting = false;
          break;

        case 'complete':
          this.isPolling = false;
          this.isInProgress = false;
          this.isStarting = false;
          this.status = null;
          this.statusHintCode = null;
          window.location.hash = '';
          this.completed.emit(response);
          break;

        default:
          console.warn(
            `${this.TAG} pollCollect returned unknown status '${response.status}'`,
          );
          this.isPolling = false;
          break;
      }
    }
  }

  private async cancel() {
    if (this.isCancelling || !this.isInProgress) return;

    this.isCancelling = true;
    this.isPolling = false;

    try {
      await this.post(this.cancelUrl);
    } finally {
      this.isCancelling = false;
      await this.reset(true); // skip the cancel request inside reset
    }
  }

  private async reset(skipCancel = false) {
    if (this.isInProgress && !skipCancel) {
      this.isCancelling = true;
      await this.post(this.cancelUrl);
    }

    window.history.pushState({}, '', null);
    this.isInProgress = false;
    this.isStarting = false;
    this.isStartingOnAnotherDevice = false;
    this.isCancelling = false;
    this.statusHintCode = null;
    this.status = null;
    this.qrCodeImageUrl = null;
    this.setFlowTypeBasedOnDevice();
    this.isPolling = false;

    // Every caller of reset() - the explicit cancel button, the Alert's
    // own "try again" after a failure, a dropped/mismatched poll response
    // - represents the same observable transition back to idle. Emitting
    // it here once, rather than only from cancel() as before, means a
    // consuming app's own "is a BankID attempt in progress" state (e.g.
    // hiding an alternate login form while this widget is active) gets a
    // signal to reset too, regardless of which path got the widget back
    // to idle. Previously only the explicit cancel button fired this -
    // "try again" silently reset the widget's own state with no signal at
    // all, leaving a consuming app's "ongoing" flag stuck true forever.
    this.cancelled.emit();
  }

  private createReturnUrl() {
    const device = useDevice();
    const { protocol, host, pathname, search } = window.location;

    // Rebuild URL without any hash
    const baseUrl = `${protocol}//${host}${pathname}${search}`;

    // Device-specific deep links
    if (device.isChromeOnAppleDevice || device.isChromeOnAndroidMobile)
      return encodeURIComponent('googlechrome://');
    if (device.isFirefoxOnAppleDevice) return encodeURIComponent('firefox://');
    if (device.isOperaTouchOnAppleDevice)
      return encodeURIComponent(
        `${baseUrl.replace('http', 'touch-http')}#initiated=true`,
      );

    // Default return URL with clean hash
    return encodeURIComponent(`${baseUrl}#initiated=true`);
  }

  private async post(url: string) {
    try {
      const response = await this.axios.post(url);
      return response.data;
    } catch (error) {
      console.error(`${this.TAG} request failed`, error);
      return null;
    }
  }

  private delay(ms: number) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}
